// Spiral parameters
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) * 0.7;
const angleStep = 0.03;
const depth = 8;
const colorVariation = 0.2;

// Draw spiral
let angle = 0;
let radius = 0;
let count = 0;

while (count < depth) {
    // Calculate position on spiral
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY - Math.sin(angle) * radius;

    // Draw segment
    if (count > 0) {
        ctx.beginPath();
        ctx.moveTo(prevX, prevY);
        ctx.lineTo(x, y);
        ctx.strokeStyle = `hsl(${h}, ${s}%, ${l}%)`;
        ctx.lineWidth = 1;
        ctx.stroke();
    }

    // Update previous position
    prevX = x;
    prevY = y;

    // Update radius and angle
    radius += 5;
    angle += angleStep;

    // Alternate hue for depth effect
    h = (count % 2 === 0) ? 180 : 200;

    // Increase saturation and lightness for depth
    s = 80 + (count * 10);
    l = 40 + (count * 10);

    count++;
}

