// Draw jellyfish body
const centerX = W / 2;
const centerY = H / 2;
const radius = 40;

// Main body
ctx.fillStyle = '#4a90e2';
ctx.beginPath();
ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
ctx.fill();

// Tentacles
ctx.fillStyle = '#556b7a';
for (let i = 0; i < 8; i++) {
    const angle = (i * Math.PI / 4) - Math.PI/2;
    const x = centerX + Math.cos(angle) * (radius + 20);
    const y = centerY + Math.sin(angle) * (radius + 20);

    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + Math.cos(angle) * 20, y + Math.sin(angle) * 20);
    ctx.lineTo(x + Math.cos(angle) * 20 + Math.sin(angle) * 10, y + Math.sin(angle) * 20 - Math.cos(angle) * 10);
    ctx.closePath();
    ctx.fill();
}

// Glow effect
ctx.globalAlpha = 0.3;
ctx.fillStyle = '#4a90e2';
ctx.beginPath();
ctx.arc(centerX, centerY, radius + 10, 0, Math.PI * 2);
ctx.fill();
ctx.globalAlpha = 1.0;

